class SensibilityJudgment:
    """SensibilityJudgment: timed sensibility judgment task on novel compound nonwords.

    Design (Günther & Marelli, 2020, Experiment 1, Method / Procedure): a timed sensibility judgment task on novel compound nonwords. Each
    participant is assigned one of six counterbalanced stimulus sets (five of
    250 novel compound nonwords plus one of 249; see Experiment 1,
    Method, item selection) and judges every item with a binary C/N key press;
    all stimuli are novel compound nonwords so the correct answer is always N.
    Each item was preceded by a fixation cross (250 ms) and followed by a
    blank screen (250 ms).

    Per-comp lexical predictors (family sizes, as-constituent frequencies,
    free-word frequencies, simuv/simuco/simvco composition similarities, and
    length) are taken verbatim from the dataset.

    ASSUMPTION: the paper says presentation order was randomized for each
    participant, but every participant on a given list in the shipped data
    shares the exact same (canonical) sequence; this simulator follows the
    data and presents each assigned list in its canonical order.
    ASSUMPTION: response times are simulated as draws from a log-normal
    distribution fit to the experiment's within-window RTs (100-5000 ms;
    exp0: mean 6.847, sd 0.444), matching the "in {rt} ms" narration.
    ASSUMPTION: participant_id is an arbitrary integer (the source carries
    non-PII numeric subject IDs); age/gender/lang/Handedness are per-participant
    demographics a text simulator cannot produce, so they are dropped from the
    DataFrame.
    """

    def __init__(self):
        self.name = "gnther_2020_trying_exp0"

    def simulate(self, agent, num_simulations, max_chars=None):
        rows, prompts = [], []
        for participant in tqdm(range(num_simulations)):
            comps = STIMULUS_LISTS[np.random.randint(len(STIMULUS_LISTS))]
            prompt = INSTRUCTIONS
            for trial, comp in enumerate(comps):
                if max_chars is not None and len(prompt) >= max_chars:
                    break
                props = COMPOUND_PROPS[comp]
                prompt += f'You see the compound "{comp}". You press [HUMAN_RESPONSE]'
                letter = agent(prompt, choice_options=["C", "N"])
                rt = int(np.round(np.random.lognormal(6.847, 0.444)))
                response = 67 if letter == "C" else 78
                ok = "correct" if response == 78 else "incorrect"
                prompt += (f'{letter}[/HUMAN_RESPONSE] ({VERDICT[letter]}), '
                           f'in {rt} ms ({ok}; the correct answer was '
                           f'{CORRECT_RESP}).\n')
                rec = {"participant_id": participant, "trial": trial, "comp": comp,
                       "rt": rt, "response": response, "word_validity": "nonword",
                       "correct_response": "n", "correct": 1 if response == 78 else 0}
                for cname, val in zip(PROP_ORDER, props):
                    rec[cname] = val
                rows.append(rec)
            prompts.append(prompt.strip())
        df = pd.DataFrame(rows, columns=[
            "participant_id", "trial", "comp", "rt", "response",
            "word_validity", "correct_response", "correct",
        ] + PROP_ORDER)
        return df, prompts


def _random_agent(prompt, choice_options):
    return str(np.random.choice(choice_options))


def main():
    parser = argparse.ArgumentParser(
        description="Smoke-test this simulator with a uniform-random agent.")
    parser.add_argument("-n", "--num-simulations", type=int, default=3,
                        help="number of simulated participants (default: 3)")
    parser.add_argument("--max-chars", type=int, default=None,
                        help="stop each participant at the trial boundary at/past this many chars")
    parser.add_argument("--seed", type=int, default=None,
                        help="numpy random seed, for reproducible runs")
    args = parser.parse_args()

    if args.seed is not None:
        np.random.seed(args.seed)

    task = SensibilityJudgment()
    df, prompts = task.simulate(_random_agent, args.num_simulations,
                                max_chars=args.max_chars)

    print(f"name: {task.name}")
    print(f"df shape: {df.shape}")
    print("dtypes:")
    print(df.dtypes.to_string())
    print("head:")
    print(df.head(8).to_string())
    print(f"prompt lengths: {[len(p) for p in prompts]}")
    for i, p in enumerate(prompts):
        first = p.splitlines()[0]
        if len(first) > 180:
            first = first[:90] + " … " + first[-90:]
        print(f"participant {i} first line: {first}")
    print("=" * 78)
    print("first prompt, head:")
    print(prompts[0][:600])
    print("...")
    print("first prompt, tail:")
    print(prompts[0][-300:])


if __name__ == "__main__":
    main()
